func classifyAllImages(urls: [URL]) async throws -> [ImageFile] {
    var images = [ImageFile]()

    try await withThrowingTaskGroup(of: ImageFile.self) { group in
        for url in urls {
            group.addTask {
                return try await classifyImage(url: url)
            }
        }

        for try await image in group {
            images.append(image)
        }
    }

    return images
}
```

